-- =====================================================================
-- Memorepe — Crea el banco "Señales y situaciones de tránsito – Provincia de Buenos Aires"
-- 1) Borra el banco vacío con ese título (solo si tiene 0 preguntas).
-- 2) Lo crea completo: 186 preguntas con imagen.
-- Correr COMPLETO una vez en el SQL Editor de Supabase.
-- =====================================================================

delete from favorites        where quiz_id in (select q.id from quizzes q where q.title = 'Señales y situaciones de tránsito – Provincia de Buenos Aires' and not exists (select 1 from questions x where x.quiz_id = q.id));
delete from exam_quizzes     where quiz_id in (select q.id from quizzes q where q.title = 'Señales y situaciones de tránsito – Provincia de Buenos Aires' and not exists (select 1 from questions x where x.quiz_id = q.id));
delete from study_sessions   where quiz_id in (select q.id from quizzes q where q.title = 'Señales y situaciones de tránsito – Provincia de Buenos Aires' and not exists (select 1 from questions x where x.quiz_id = q.id));
delete from quizzes q
where q.title = 'Señales y situaciones de tránsito – Provincia de Buenos Aires'
  and not exists (select 1 from questions x where x.quiz_id = q.id);

-- Señales y situaciones de tránsito – Provincia de Buenos Aires (186 preguntas)
do $$
declare
  v_user uuid;
  v_quiz uuid;
  v_q uuid;
begin
  select id into v_user from users where username = 'memorepe';
  if v_user is null then raise exception 'No existe el usuario @memorepe'; end if;
  if exists (select 1 from quizzes where title = 'Señales y situaciones de tránsito – Provincia de Buenos Aires') then raise notice 'Ya existe: Señales y situaciones de tránsito – Provincia de Buenos Aires'; return; end if;
  values (v_user, 'Señales y situaciones de tránsito – Provincia de Buenos Aires', 'Señales de tránsito, señas y situaciones reales del cuestionario oficial del examen teórico de manejo de la Provincia de Buenos Aires, con imágenes y respuestas correctas.', 'otro', 'conducir', 'es', 'public', 'Provincia de Buenos Aires', 'Señales de tránsito', 'senales-situaciones-transito-provincia-buenos-aires')
  returning id into v_quiz;
  update quizzes set question_count = (select count(*) from questions where quiz_id = v_quiz) where id = v_quiz;
  raise notice 'Creado: % con % preguntas', 'Señales y situaciones de tránsito – Provincia de Buenos Aires', 186;
end $$;
