  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, '¿Cuál es la “distancia mínima de seguridad” a la que debe circular el vehículo A con respecto al B?', 'single', 'Respuesta según el cuestionario oficial de la Provincia de Buenos Aires.', 132, '/img/preguntas/pba/0141.webp') returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'A una diferencia de dos segundos.', true, 0), (v_q, 'A una distancia de 2 metros.', false, 1), (v_q, 'No existe una determinada. Sólo está prohibido circular inmediatamente detrás, sin dejar distancia.', false, 2);
  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, '¿Cuál es la manera más adecuada de conducir un vehículo en este tramo de la ruta?', 'single', 'Respuesta según el cuestionario oficial de la Provincia de Buenos Aires.', 133, '/img/preguntas/pba/0142.webp') returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Aumentar la velocidad gradualmente antes de ingresar en la curva.', false, 0), (v_q, 'Desacelerar antes de ingresar a la curva.', true, 1), (v_q, 'Mantener la misma velocidad antes de la curva y acelerar mientras se circula en ella.', false, 2);
  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, '¿El vehículo de la imagen se encuentra en infracción?', 'single', 'Respuesta según el cuestionario oficial de la Provincia de Buenos Aires.', 134, '/img/preguntas/pba/0143.webp') returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Sí, salvo que el propietario del vehículo sea el mismo que el de la vivienda.', false, 0), (v_q, 'No, ya que hay espacio suficiente para el paso del peatón.', false, 1), (v_q, 'Ambas respuestas, A y B, son incorrectas.', true, 2);
  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, 'El vehículo con la oblea universal de discapacidad que se muestra en esta imagen, ¿se encuentra en infracción?', 'single', 'Respuesta según el cuestionario oficial de la Provincia de Buenos Aires.', 135, '/img/preguntas/pba/0144.webp') returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'No, ya que al portar la oblea universal de discapacidad tiene libre estacionamiento y por ello puede estacionar en este lugar.', false, 0), (v_q, 'Sí. Todo vehículo tiene prohibido estacionar en este sector ya que pone en riesgo a pasajeros y peatones.', true, 1);
  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, '¿Es correcta la detención del vehículo en este sector?', 'single', 'Respuesta según el cuestionario oficial de la Provincia de Buenos Aires.', 136, '/img/preguntas/pba/0145.webp') returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Sí, ya que se encuentra con balizas encendidas.', false, 0), (v_q, 'Sí, porque sólo está prohibido el estacionamiento.', false, 1), (v_q, 'No, ya que tanto la detención como el estacionamiento en este sector se encuentra prohibido.', true, 2);
  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, 'Como norma general, frente a esta señal, ¿está permitido detenerse para el ascenso o descenso de pasajeros?', 'single', 'Respuesta según el cuestionario oficial de la Provincia de Buenos Aires.', 137, '/img/preguntas/pba/0146.webp') returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'No. Está prohibido estacionar y detenerse.', false, 0), (v_q, 'Sí. Sólo está prohibido estacionar pero no detenerse.', true, 1), (v_q, 'Según la hora en que quiera realizarse la detención.', false, 2);
  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, '¿Está permitida la acción que se presenta en la siguiente imagen?', 'single', 'Respuesta según el cuestionario oficial de la Provincia de Buenos Aires.', 138, '/img/preguntas/pba/0147.webp') returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Sí, porque tiene las balizas encendidas y no necesita permanecer más de 5 minutos para que descienda un pasajero.', false, 0), (v_q, 'Sí, porque la doble fila está permitida cuando se trata de ascenso y descenso de pasajeros.', false, 1), (v_q, 'No, ya que la doble fila está permitida sólo como detención previa a la maniobra de estacionamiento.', true, 2);
  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, '¿Este vehículo se encuentra bien estacionado?', 'single', 'Respuesta según el cuestionario oficial de la Provincia de Buenos Aires.', 139, '/img/preguntas/pba/0148.webp') returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Sí. Al no estar el cordón pintado de amarillo, está habilitado a estacionarse y detenerse.', false, 0), (v_q, 'Sí. Al no estar el cordón pintado de rojo, está habilitado a estacionarse pero no a detenerse.', false, 1), (v_q, 'No, porque debería estar más alejado del cordón (a 20 cm de él).', true, 2);
  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, '¿Qué precauciones se deben tener al dejar estacionado un vehículo en esta situación?', 'single', 'Respuesta según el cuestionario oficial de la Provincia de Buenos Aires.', 140, '/img/preguntas/pba/0149.webp') returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Orientar las ruedas hacia el cordón de la vereda y dejar la marcha hacia atrás o en posición de estacionamiento en el caso de tener caja automática.', false, 0), (v_q, 'Orientar las ruedas hacia el centro de la calzada y dejar la marcha en primera o en posición de estacionamiento en el caso de tener caja automática.', true, 1), (v_q, 'Orientar las ruedas paralelas al cordón y sin cambio o en posición de estacionamiento en el caso de tener caja automática.', false, 2);
  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, '¿Se está habilitado a detener un vehículo en este lugar?', 'single', 'Respuesta según el cuestionario oficial de la Provincia de Buenos Aires.', 141, '/img/preguntas/pba/0151.webp') returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Sí, siempre y cuando no entorpezca la circulación.', false, 0), (v_q, 'No, está prohibido estacionar y detenerse por normativa.', true, 1), (v_q, 'Si, a menos que haya una señal que lo prohíba expresamente.', false, 2);
  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, 'Si el vehículo que lo precede, circula con estas luces intermitentes encendidas, ¿qué podría estar indicando el conductor?', 'single', 'Respuesta según el cuestionario oficial de la Provincia de Buenos Aires.', 142, '/img/preguntas/pba/0152.webp') returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Que el vehículo circula lentamente.', false, 0), (v_q, 'Que el vehículo próximamente ingresará a un garage o se detendrá.', true, 1), (v_q, 'Que el vehículo realizará un giro en la próxima intersección.', false, 2);
  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, '¿Qué indica el uso de este tipo de luces?', 'single', 'Respuesta según el cuestionario oficial de la Provincia de Buenos Aires.', 143, '/img/preguntas/pba/0153.webp') returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Cuando se utilizan por separado sirven para preanunciar maniobras.', false, 0), (v_q, 'Cuando se utilizan a la vez sirven para anunciar situaciones de emergencias o que se está por detener.', false, 1), (v_q, 'Ambas respuestas, la A y la B, son correctas.', true, 2);
  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, 'Si el vehículo de la imagen se dispone a ingresar a un garaje, está anticipando su maniobra, utilizando las luces correctas.', 'single', 'Respuesta según el cuestionario oficial de la Provincia de Buenos Aires.', 144, '/img/preguntas/pba/0154.webp') returning id into v_q;
