  insert into options (question_id, body, is_correct, "order") values (v_q, 'Como acompañamiento al uso de balizas y/o en caso de emergencia.', true, 0), (v_q, 'Nunca.', false, 1), (v_q, 'Sólo cuando se utilicen en calles.', false, 2);
  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, 'El vehículo, señalado con un círculo rojo, circula utilizando las luces correctas.', 'single', 'Respuesta según el cuestionario oficial de la Provincia de Buenos Aires.', 147, '/img/preguntas/pba/0157.webp') returning id into v_q;
