  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, 'Al observar las luces de este vehículo, ¿qué significado tienen en cuanto al sentido de circulación?', 'single', 'Respuesta según el cuestionario oficial de la Provincia de Buenos Aires.', 148, '/img/preguntas/pba/0158.webp') returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Que está circulando en mí mismo sentido.', true, 0), (v_q, 'Que está circulando en el sentido contrario al mío.', false, 1), (v_q, 'No indican sentido de circulación sino que está descompuesto.', false, 2);
  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, '¿Para qué sirven estas luces intermitentes?', 'single', 'Respuesta según el cuestionario oficial de la Provincia de Buenos Aires.', 149, '/img/preguntas/pba/0159.webp') returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Para advertir a los demás conductores, frente a malas condiciones climáticas, que el vehículo circula a baja velocidad.', false, 0), (v_q, 'Para señalizar y advertir a los demás conductores que el vehículo se encuentra detenido o próximo a una maniobra de detención, estacionamiento o emergencia.', true, 1), (v_q, 'Ambas respuestas, A y B, son correctas.', false, 2);
  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, 'Si al circular por la siguiente arteria, se ve obligado a detener en la banquina, ¿qué luces debe colocar?', 'single', 'Respuesta según el cuestionario oficial de la Provincia de Buenos Aires.', 150, '/img/preguntas/pba/0160.webp') returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Luces altas y giro.', false, 0), (v_q, 'Luces reglamentarias y balizas.', true, 1), (v_q, 'Luces antinieblas.', false, 2);
  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, '¿Qué significado tiene el color de las luces encendidas que se indican en la imagen?', 'single', 'Respuesta según el cuestionario oficial de la Provincia de Buenos Aires.', 151, '/img/preguntas/pba/0161.webp') returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Al estar ubicada en la parte posterior del vehículo, el color blanco es para diferenciarla de las luces de freno, posición y giro.', false, 0), (v_q, 'Al ser de color blanco se obtiene mejor visión cuando la maniobra de retroceso se debe realizar de noche o en condiciones de poca visibilidad.', false, 1), (v_q, 'Indica el sentido de circulación. La luz blanca significa que el vehículo circula en sentido contrario al del vehículo rojo que está detrás de él.', true, 2);
  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, 'En cuanto a la velocidad frente a esta situación, ¿qué debería considerar un conductor?', 'single', 'Respuesta según el cuestionario oficial de la Provincia de Buenos Aires.', 152, '/img/preguntas/pba/0162.webp') returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Debería circular a la mitad de la velocidad máxima establecida por Ley.', false, 0), (v_q, 'Debería adecuar la velocidad de acuerdo a las condiciones climáticas y de dicha vía de circulación.', true, 1), (v_q, 'Lo único que debería hacer es respetar es la velocidad máxima de la arteria por la que circula.', false, 2);
  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, '¿Cómo se define el efecto que ocurre en la siguiente imagen?', 'single', 'Respuesta según el cuestionario oficial de la Provincia de Buenos Aires.', 153, '/img/preguntas/pba/0163.webp') returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Aquaplaning.', true, 0), (v_q, 'Off tracking.', false, 1);
  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, 'Frente a esta condición climática, ¿se deben encender las luces bajas?', 'single', 'Respuesta según el cuestionario oficial de la Provincia de Buenos Aires.', 154, '/img/preguntas/pba/0164.webp') returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Sí, siempre que está disminuida la visibilidad.', true, 0), (v_q, 'No, porque las luces sólo deben utilizarse por la noche.', false, 1), (v_q, 'Sí, pero sólo en rutas.', false, 2);
  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, 'Al conducir por un largo lapso de tiempo y en esta condición climática…', 'single', 'Respuesta según el cuestionario oficial de la Provincia de Buenos Aires.', 155, '/img/preguntas/pba/0165.webp') returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Es menos probable que aparezca la fatiga, ya que aumenta la atención.', false, 0), (v_q, 'Es necesario descansar con más frecuencia, para evitar la fatiga.', true, 1), (v_q, 'No influye en la aparición de fatiga, siempre y cuando se mantenga una velocidad prudente.', false, 2);
  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, 'Bajo esta condición climática, ¿es recomendable aumentar la distancia de seguridad y reducir la velocidad?', 'single', 'Respuesta según el cuestionario oficial de la Provincia de Buenos Aires.', 156, '/img/preguntas/pba/0166.webp') returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'No, al reducir la velocidad, mayor es la proporción de agua en el asfalto.', false, 0), (v_q, 'Sí, con lluvia la adherencia es menor.', true, 1), (v_q, 'No. La distancia de seguridad debe ser siempre la misma.', false, 2);
  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, 'Cuando conduce bajo esta condición climática, ¿a cuánto se debe incrementar la regla de 2 segundos en la distancia de seguridad?', 'single', 'Respuesta según el cuestionario oficial de la Provincia de Buenos Aires.', 157, '/img/preguntas/pba/0167.webp') returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'A 4 segundos.', true, 0), (v_q, 'A 3 segundos.', false, 1), (v_q, 'A 5 segundos.', false, 2);
  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, 'Al conducir sobre una calzada en estas condiciones, la distancia de frenado será...', 'single', 'Respuesta según el cuestionario oficial de la Provincia de Buenos Aires.', 158, '/img/preguntas/pba/0168.webp') returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Igual que cuando la calzada se encuentra seca.', false, 0), (v_q, 'Menor que cuando la calzada se encuentra seca.', false, 1), (v_q, 'Mayor que cuando la calzada se encuentra seca.', true, 2);
  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, 'En estas condiciones, ¿una incorrecta regulación de la altura de las luces bajas puede producir encandilamiento?', 'single', 'Respuesta según el cuestionario oficial de la Provincia de Buenos Aires.', 159, '/img/preguntas/pba/0169.webp') returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Sí, porque este efecto se produce por cambios bruscos en la intensidad de la luz.', true, 0), (v_q, 'No, porque este efecto se produce sólo por el uso de la luz alta.', false, 1), (v_q, 'No, porque este efecto se produce en rutas con poca iluminación.', false, 2);
  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, '¿Cuál es el límite de velocidad máxima en esta situación?', 'single', 'Respuesta según el cuestionario oficial de la Provincia de Buenos Aires.', 160, '/img/preguntas/pba/0170.webp') returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, '60 km/h.', true, 0), (v_q, '80 km/h.', false, 1), (v_q, '40 km/h.', false, 2);
