  insert into options (question_id, body, is_correct, "order") values (v_q, 'Utilizar las luces rompeniebla, lo cual es suficiente porque permite ampliar la visibilidad del conductor.', false, 0), (v_q, 'Conducir con ambas manos en el volante, reducir la velocidad, aumentar la distancia entre vehículos y utilizar las luces correspondientes del vehículo.', true, 1), (v_q, 'Detenerse en la banquina hasta que levante el banco de niebla.', false, 2);
  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, 'Con estas condiciones climáticas, ¿qué luces debe utilizar para poder circular en esta ruta?', 'single', 'Respuesta según el cuestionario oficial de la Provincia de Buenos Aires.', 162, '/img/preguntas/pba/0172.webp') returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Las luces altas, durante todo el recorrido mientras continúe la niebla.', false, 0), (v_q, 'Las luces bajas y las rompeniebla (en el caso de tenerlas).', true, 1), (v_q, 'Las luces bajas, las rompenieblas (en caso de tenerlas) y las balizas.', false, 2);
  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, '¿En qué caso deberán utilizarse estas luces?', 'single', 'Respuesta según el cuestionario oficial de la Provincia de Buenos Aires.', 163, '/img/preguntas/pba/0173.webp') returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Únicamente de noche y por una vía sin asfaltar.', false, 0), (v_q, 'Sólo por vías sin banquina.', false, 1), (v_q, 'En vías afectadas por niebla, en cualquier horario.', true, 2);
  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, 'Si se encuentra en esta vía bajo estas condiciones climáticas, ¿lo más conveniente es detenerse en la banquina?', 'single', 'Respuesta según el cuestionario oficial de la Provincia de Buenos Aires.', 164, '/img/preguntas/pba/0174.webp') returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Sí, cuando el banco de niebla es muy denso.', false, 0), (v_q, 'Sí, siempre y cuando se coloquen las luces altas para ser más visibles.', false, 1), (v_q, 'No. Si no hay posibilidad de circular, debe alejarse lo más posible de la calzada y de la banquina.', true, 2);
  insert into questions (quiz_id, body, type, explanation, "order", image_url) values (v_quiz, 'Si ud. circula por la ruta y observa esta situación, debe…', 'single', 'Respuesta según el cuestionario oficial de la Provincia de Buenos Aires.', 165, '/img/preguntas/pba/0175.webp') returning id into v_q;
