  insert into options (question_id, body, is_correct, "order") values (v_q, 'Es indistinto mientras que no resbalen.', false, 0), (v_q, 'Sólo puede verse afectada la conducción en viajes largos.', false, 1), (v_q, 'No, sólo un calzado sujeto al pie brinda seguridad en la conducción.', true, 2);
